+          this.startBrowser();
+          return null;
+        }
+        this.deps.onError(this.deps.unsupportedMessage());
+        return null;
+      }
+    } finally {
+      this.stopInFlight = false;
+    }
+  }
+
+  private async transcribeProviderResponse(
+    gen: number,
+    response: StopRecordingResponse,
