+      await this.deps.transcribe({ samples, sampleRate })
+    ).trim();
+    if (gen !== this.opGen || this.disposed) return null;
+    return transcript || null;
+  }
+
+  private setIdle(preserveFinalResult = false): void {
+    const wasListening = this.state !== "idle";
