+  return [Number(rgb[1]), Number(rgb[2]), Number(rgb[3])];
+};
+
+const linearize = (channel: number) => {
+  const c = channel / 255;
+  return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
