+        match percent_decode_route_path_once(&decoded) {
+            Ok(next) => {
+                if next == decoded {
+                    return Ok(decoded);
+                }
+                decoded = next;
+            }
+            Err(e) if iteration > 0 => {
+                last_error = Some(e);
+                break;
+            }
+            Err(e) => return Err(e),
+        }
+    }
