+        if let Some(err) = last_error {
+            return Err(err);
+        }
+        let still_encoded = decoded.as_bytes().windows(3).any(|w| {
+            w[0] == b'%' && hex_value(w[1]).is_some() && hex_value(w[2]).is_some()
+        });
+        if still_encoded {
+            return Err("Floating app route has excessive percent encoding".to_string());
+        }
+    }
+    Ok(decoded)
